1	// Runs inside the YouTube page itself (not the extension's isolated world) so it
2	// can use YouTube's player. YouTube serves captions only to requests carrying a
3	// token its player adds, so this notes the player's own caption request and
4	// reads the same address. When captions are off, it turns them on for a
5	// moment, hidden, so the player asks, then turns them off again. The player
6	// ignores that until the video itself plays, so it waits out any ad first.
7	// It reads only when content.ts asks, so it leaves YouTube alone while the
8	// extension is off.
9	import {
10	  CONTENT_SOURCE,
11	  PAGE_HOOK_SOURCE,
12	  type ContentMessage,
13	  type PageHookMessage,
14	} from "./messages.ts";
15	import { parseJson3, pickCaptionTrack, type CaptionTrack } from "./youtube.ts";
16	
17	const PLAYER_WAIT_MS = 30_000;
18	// Long enough for ads, or for a viewer who opens a video and presses play later.
19	const CAPTIONS_WAIT_MS = 10 * 60_000;
20	const ASK_EVERY_MS = 5_000;
21	const ASK_FOR_MS = 3_000;
22	const POLL_MS = 250;
23	
24	interface PlayerResponse {
25	  videoDetails?: { videoId?: string; title?: string; author?: string };
26	  captions?: {
27	    playerCaptionsTracklistRenderer?: { captionTracks?: CaptionTrack[] };
28	  };
29	}
30	
31	/** The parts of YouTube's player element (#movie_player) used here. */
32	interface Player extends HTMLElement {
33	  getPlayerResponse(): PlayerResponse | undefined;
34	  /** -1 until the video starts; YouTube reports the ad's state during an ad. */
35	  getPlayerState(): number;
36	  loadModule(module: "captions"): void;
37	  getOption(
38	    module: "captions",
39	    option: "track",
40	  ): Partial<CaptionTrack> | undefined;
41	  setOption(
42	    module: "captions",
43	    option: "track",
44	    track: Partial<CaptionTrack>,
45	  ): void;
46	}
