1	// Runs in the extension's isolated world on youtube.com. Takes the captions
2	// page-hook.ts reads, asks the local server (through background.ts) for the
3	// claims worth checking, and checks each one a few minutes before it's said.
4	// Shows the results in three places: a toggle in the player's controls with
5	// the count, a chip on the video as each claim is said, and a list beside the
6	// video with every verdict and its sources.
7	import type { Claim, Verdict } from "../server/checker.ts";
8	import {
9	  CONTENT_SOURCE,
10	  PAGE_HOOK_SOURCE,
11	  type CheckClaimResponse,
12	  type ContentMessage,
13	  type FindClaimsResponse,
14	  type PageHookMessage,
15	  type PickClaimResponse,
16	  type ServerRequest,
17	  ENABLED_KEY,
18	  readEnabled,
19	} from "./messages.ts";
20	import {
21	  formatTime,
22	  parseTime,
23	  quoteStart,
24	  transcriptText,
25	  type Cue,
26	} from "./youtube.ts";
27	
28	const TOGGLE_ID = "vfc-toggle";
29	const PICK_ID = "vfc-pick";
30	const LIST_ID = "vfc-list";
31	const OPEN_ITEM_ID = "vfc-open";
32	const CHIPS_ID = "vfc-chips";
33	const STYLE_ID = "vfc-style";
34	// Checks run this far ahead of the playhead, so verdicts are ready when a
35	// claim is said and nothing past where the viewer stops gets paid for.
36	const LOOKAHEAD_SECONDS = 180;
37	const PARALLEL_CHECKS = 2;
38	// A late verdict still gets its chip this long after the claim is said.
39	const CHIP_WINDOW_SECONDS = 20;
40	const RED_CHIP_MS = 8000;
41	const VERDICT_CHIP_MS = 6000;
42	const CHECKING_CHIP_MS = 4000;
43	// "Check what was just said" looks back this far in the captions.
44	const PICK_SECONDS = 20;
45	// YouTube already uses C for captions; V is free ("verify").
46	const PICK_KEY = "v";
47	
48	type Check =
49	  | { state: "waiting" }
50	  | { state: "checking" }
51	  | { state: "done"; verdict: Verdict }
52	  | { state: "failed"; error: string };
53	
54	interface LiveClaim extends Claim {
55	  /** When it's said, in seconds. */
56	  seconds: number;
57	  check: Check;
58	  /** Its chip so far: none yet, one while checking, or one with the verdict. */
59	  chip: "none" | "pending" | "final";
60	}
61	
62	type Status =
63	  | { state: "finding" }
64	  | {
65	      state: "ready";
66	      videoId: string;
67	      title: string;
68	      cues: Cue[];
69	      claims: LiveClaim[];
70	    }
71	  | { state: "noCaptions" }
72	  | { state: "error"; reason: string; retry: () => void };
73	
74	type Tone = "red" | "green" | "grey";
75	
76	let status: Status = { state: "finding" };
77	let statusVideoId: string | null = null;
78	/** Off until the saved setting is read, so nothing reaches the server early. */
79	let enabled = false;
80	let listOpen = false;
81	/** The claim whose explanation and sources are open in the list. */
82	let openClaim: LiveClaim | null = null;
83	/** True while "Check what was just said" waits for the server; one at a time. */
84	let picking = false;
85	/** What the last "Check what was just said" found, when it found no claim to show. */
86	let pickNote: string | null = null;
87	const chipTimers = new WeakMap<HTMLElement, number>();
88	const chipsByClaim = new WeakMap<LiveClaim, HTMLButtonElement>();
89	
90	/** The video on the page, from its address; null off a watch page. */
91	function currentVideoId(): string | null {
92	  if (location.pathname !== "/watch") return null;
93	  return new URLSearchParams(location.search).get("v");
94	}
95	
96	function playerVideo(): HTMLVideoElement | null {
97	  return document.querySelector("#movie_player video");
98	}
99	
100	/** During an ad, the player's video and its time belong to the ad. */
101	function adShowing(): boolean {
102	  return Boolean(
103	    document.getElementById("movie_player")?.classList.contains("ad-showing"),
104	  );
105	}
106	
107	function setStatus(next: Status): void {
108	  status = next;
109	  statusVideoId = currentVideoId();
110	  if (next.state !== "ready") document.getElementById(CHIPS_ID)?.remove();
111	  render();
112	}
113	
114	window.addEventListener("message", (event: MessageEvent<PageHookMessage>) => {
115	  const message = event.data;
116	  if (event.source !== window || message?.source !== PAGE_HOOK_SOURCE) return;
117	  // An answer about a video the viewer has already left.
118	  if (message.videoId !== currentVideoId()) return;
119	  switch (message.type) {
120	    case "reading":
121	      return setStatus({ state: "finding" });
122	    case "noCaptions":
123	      return setStatus({ state: "noCaptions" });
124	    case "captionError":
125	      return setStatus({
126	        state: "error",
127	        reason: `Couldn't read the captions: ${message.error}`,
128	        retry: readCaptionsAgain,
129	      });
130	    case "captions":
131	      return void findClaims(message.videoId, message.title, message.cues);
132	  }
133	});
134	
135	function tellPageHook(type: ContentMessage["type"]): void {
136	  const message: ContentMessage = { source: CONTENT_SOURCE, type };
137	  window.postMessage(message, window.location.origin);
138	}
139	
140	function setEnabled(next: boolean): void {
141	  if (next === enabled) return;
