361	/** Finds the claim in the last PICK_SECONDS of captions and checks it. */
362	async function checkWhatWasJustSaid(): Promise<void> {
363	  const video = playerVideo();
364	  if (!enabled || status.state !== "ready" || !video || picking || adShowing())
365	    return;
366	  video.pause();
367	  if (document.fullscreenElement) await document.exitFullscreen();
368	  const { videoId, title, cues, claims } = status;
369	  const now = video.currentTime;
370	  const from = now - PICK_SECONDS;
371	  listOpen = true;
372	  pickNote = null;
373	  // A claim already in the list from these seconds: show it rather than pay
374	  // again.
375	  // ponytail: assumes it's the one the viewer meant; a second, different claim
376	  // in the same 20 seconds can't be picked.
377	  const known = claims
378	    .filter((claim) => claim.seconds >= from && claim.seconds <= now + 1)
379	    .at(-1);
380	  if (known) {
381	    openClaim = known;
382	    render();
383	    if (known.check.state === "waiting") void checkClaim(known);
384	    return scrollToOpen();
385	  }
386	  const recent = cues.filter((cue) => cue.start >= from && cue.start <= now);
387	  if (recent.length === 0) {
388	    pickNote = "No captions in the last 20 seconds, so nothing to check here.";
389	    return render();
390	  }
391	  picking = true;
392	  pickNote = "Finding the claim you just heard…";
393	  render();
394	  const response = await askServer<PickClaimResponse>({
395	    type: "pickClaim",
396	    videoId,
397	    title,
398	    excerpt: transcriptText(recent),
399	  });
400	  picking = false;
401	  if (status.state !== "ready" || status.videoId !== videoId) return;
402	  if (!response.ok) {
403	    pickNote = `Couldn't check what was just said: ${response.error}`;
404	    return render();
405	  }
406	  if (!response.claim) {
407	    pickNote =
408	      "Nothing to check in the last 20 seconds: no facts, figures, or forecasts.";
409	    return render();
410	  }
411	  pickNote = null;
412	  const lineStart = parseTime(response.claim.time) ?? recent[0].start;
413	  const claim: LiveClaim = {
414	    ...response.claim,
415	    seconds: quoteStart(cues, response.claim.quote, lineStart),
416	    check: { state: "waiting" },
417	    chip: "none",
418	  };
419	  status.claims = [...status.claims, claim].sort(
420	    (a, b) => a.seconds - b.seconds,
421	  );
422	  openClaim = claim;
423	  render();
424	  scrollToOpen();
425	  void checkClaim(claim);
426	}
