31	/** The parts of YouTube's player element (#movie_player) used here. */
32	interface Player extends HTMLElement {
33	  getPlayerResponse(): PlayerResponse | undefined;
34	  /** -1 until the video starts; YouTube reports the ad's state during an ad. */
35	  getPlayerState(): number;
36	  loadModule(module: "captions"): void;
37	  getOption(
38	    module: "captions",
39	    option: "track",
40	  ): Partial<CaptionTrack> | undefined;
41	  setOption(
42	    module: "captions",
43	    option: "track",
44	    track: Partial<CaptionTrack>,
45	  ): void;
46	}
47	
48	/** Video id → the address of the player's latest caption request for it. */
49	const captionAddresses = new Map<string, string>();
50	new PerformanceObserver((list) => {
51	  for (const { name } of list.getEntries()) {
52	    if (!name.includes("/api/timedtext") || !name.includes("pot=")) continue;
53	    const videoId = new URL(name).searchParams.get("v");
54	    if (videoId) captionAddresses.set(videoId, name);
55	  }
56	}).observe({ type: "resource" });
