58	/** The video being read or read already; null after a failure or a stop. */
59	let readingVideoId: string | null = null;
60	
61	/** The video on the page, from its address; null off a watch page. */
62	function currentVideoId(): string | null {
63	  if (location.pathname !== "/watch") return null;
64	  return new URLSearchParams(location.search).get("v");
65	}
