67	async function readCaptions(): Promise<void> {
68	  const videoId = currentVideoId();
69	  if (!videoId || videoId === readingVideoId) return;
70	  readingVideoId = videoId;
71	  post({ type: "reading", videoId });
72	  try {
73	    // Right after YouTube changes video, the player may still describe the old one.
74	    const player = await waitFor(() => {
75	      const element = document.getElementById("movie_player") as Player | null;
76	      const playing = element?.getPlayerResponse?.()?.videoDetails?.videoId;
77	      return playing === videoId ? element : null;
78	    }, "YouTube's player didn't load");
79	    const response = player.getPlayerResponse() ?? {};
80	    const track = pickCaptionTrack(
81	      response.captions?.playerCaptionsTracklistRenderer?.captionTracks ?? [],
82	    );
83	    if (!track) return post({ type: "noCaptions", videoId });
84	
85	    const address = new URL(await captionAddress(player, track, videoId));
86	    address.searchParams.set("fmt", "json3");
87	    const captions = await (await fetch(address)).json();
88	    if (readingVideoId !== videoId) return; // Stopped while fetching.
89	    const { title = "", author = "" } = response.videoDetails ?? {};
90	    post({
91	      type: "captions",
92	      videoId,
93	      title: author ? `${title} (${author})` : title,
94	      cues: parseJson3(captions),
95	    });
96	  } catch (error) {
97	    // Stopped, or moved on to another video: nobody is waiting for this one.
98	    if (readingVideoId !== videoId) return;
99	    readingVideoId = null; // So a retry reads again.
100	    const reason = error instanceof Error ? error.message : String(error);
101	    post({ type: "captionError", videoId, error: reason });
102	  }
103	}
