105	/**
106	 * The address of the player's caption request for this video: the viewer's
107	 * own, if they turn captions on, or one this asks for once the video plays.
108	 */
109	async function captionAddress(
110	  player: Player,
111	  track: CaptionTrack,
112	  videoId: string,
113	): Promise<string> {
114	  const started = Date.now();
115	  let askedAt = -Infinity;
116	  for (;;) {
117	    const address = captionAddresses.get(videoId);
118	    if (address) return address;
119	    if (currentVideoId() !== videoId) throw new Error("the viewer moved on");
120	    if (readingVideoId !== videoId) throw new Error("stopped");
121	    if (Date.now() - started > CAPTIONS_WAIT_MS)
122	      throw new Error("the player didn't load captions");
123	    const captionsOn = Boolean(
124	      player.getOption("captions", "track")?.languageCode,
125	    );
126	    const videoPlaying =
127	      player.getPlayerState() !== -1 &&
128	      !player.classList.contains("ad-showing");
129	    if (!captionsOn && videoPlaying && Date.now() - askedAt > ASK_EVERY_MS) {
130	      askedAt = Date.now();
131	      await askPlayerForCaptions(player, track, videoId);
132	    } else {
133	      await sleep(POLL_MS);
134	    }
135	  }
136	}
