138	/** Turns captions on, hidden, for up to ASK_FOR_MS so the player requests them. */
139	async function askPlayerForCaptions(
140	  player: Player,
141	  track: CaptionTrack,
142	  videoId: string,
143	): Promise<void> {
144	  const hide = document.createElement("style");
145	  hide.textContent =
146	    ".ytp-caption-window-container { display: none !important; }";
147	  document.head.append(hide);
148	  try {
149	    player.loadModule("captions");
150	    player.setOption("captions", "track", {
151	      languageCode: track.languageCode,
152	      kind: track.kind,
153	    });
154	    const started = Date.now();
155	    while (
156	      !captionAddresses.has(videoId) &&
157	      readingVideoId === videoId &&
158	      Date.now() - started < ASK_FOR_MS
159	    )
160	      await sleep(POLL_MS);
161	  } finally {
162	    player.setOption("captions", "track", {});
163	    hide.remove();
164	  }
165	}
