167	/** Resolves with `check`'s first truthy answer, polling for up to PLAYER_WAIT_MS. */
168	function waitFor<T>(
169	  check: () => T | null | undefined,
170	  failure: string,
171	): Promise<T> {
172	  const started = Date.now();
173	  return new Promise((resolve, reject) => {
174	    const poll = () => {
175	      const value = check();
176	      if (value) resolve(value);
177	      else if (Date.now() - started > PLAYER_WAIT_MS)
178	        reject(new Error(failure));
179	      else setTimeout(poll, POLL_MS);
180	    };
181	    poll();
182	  });
183	}
