35	// Plain HTTP is fine here: the request never leaves this computer.
36	const SERVER = "http://127.0.0.1:8787";
37	const PATHS: Record<ServerRequest["type"], string> = {
38	  findClaims: "/claims",
39	  checkClaim: "/check",
40	  pickClaim: "/pick",
41	};
42	
43	chrome.runtime.onMessage.addListener(
44	  (message: Partial<ServerRequest>, _sender, sendResponse) => {
45	    const path = message.type && PATHS[message.type];
46	    if (!path) return false;
47	    const { type: _type, ...body } = message;
48	    void askServer(path, body).then(sendResponse);
49	    return true; // Keeps the channel open until sendResponse is called.
