53	async function askServer(path: string, body: object) {
54	  let response: Response;
55	  try {
56	    response = await fetch(`${SERVER}${path}`, {
57	      method: "POST",
58	      headers: { "Content-Type": "application/json" },
59	      body: JSON.stringify(body),
60	    });
61	  } catch {
62	    return {
63	      ok: false,
64	      error:
65	        "couldn't reach the fact-check server. Is it running? (npm run server)",
66	    };
67	  }
68	  const answer = await response.json().catch(() => ({}));
69	  return response.ok
70	    ? { ok: true, ...answer }
71	    : {
72	        ok: false,
73	        error: answer.error ?? `the server answered ${response.status}`,
74	      };
75	}
